<?php
namespace App\Http\Controllers; use App\Models\{FoodCategory,FoodRequest,FoodDonation,Reservation}; use Illuminate\Http\Request;
class RequestController extends Controller { public function index(){ $requests=FoodRequest::with('category')->where('charity_id',auth()->user()->partnerProfile->profile_id)->get(); return view('requests.index',compact('requests'));} public function create(){return view('requests.form',['foodRequest'=>new FoodRequest(),'categories'=>FoodCategory::all()]);} public function store(Request $r){$data=$this->data($r); $data['charity_id']=auth()->user()->partnerProfile->profile_id; FoodRequest::create($data); return redirect('/requests');} public function edit(FoodRequest $foodRequest){return view('requests.form',['foodRequest'=>$foodRequest,'categories'=>FoodCategory::all()]);} public function update(Request $r, FoodRequest $foodRequest){$foodRequest->update($this->data($r)); return redirect('/requests');} public function cancel(FoodRequest $foodRequest){$foodRequest->update(['request_status'=>'CANCELLED']); return back();} public function reservations(FoodRequest $foodRequest){return view('reservations.index',['foodRequest'=>$foodRequest->load('reservations.donation'),'donations'=>FoodDonation::where('donation_status','AVAILABLE')->get()]);} public function reserve(Request $r, FoodRequest $foodRequest){$d=$r->validate(['donation_id'=>'required','reserved_quantity'=>'required|numeric','pickup_deadline'=>'required|date']); Reservation::create(['request_id'=>$foodRequest->request_id]+$d); return back();} private function data(Request $r){return $r->validate(['category_id'=>'required','requested_quantity'=>'required|numeric','fulfilled_quantity'=>'nullable|numeric','unit'=>'required','request_deadline'=>'required|date','request_status'=>'nullable']);} }
